ALTER TABLE public.telegram_actions DROP CONSTRAINT telegram_actions_kind_check;
ALTER TABLE public.telegram_actions ADD CONSTRAINT telegram_actions_kind_check CHECK (kind IN ('credits','status','approve_upi','reject_upi','announcement','close_ticket','plan'));
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.telegram_confirm_action(uuid,text,text,boolean)'::regprocedure) INTO d; IF position('ELSIF a.kind=''status'' THEN' IN d)=0 THEN RAISE EXCEPTION 'ACTION_FUNCTION_CHANGED'; END IF; d:=replace(d,'ELSIF a.kind=''status'' THEN','ELSIF a.kind=''plan'' THEN IF a.message NOT IN (''free'',''creator'',''pro'',''premium'') OR a.amount IS NULL OR a.amount<0 OR a.amount>1000000 THEN RAISE EXCEPTION ''INVALID_PLAN''; END IF; SELECT * INTO p FROM public.profiles WHERE id=a.target_user FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION ''USER_NOT_FOUND''; END IF; UPDATE public.profiles SET plan=a.message,subscription_status=CASE WHEN a.message=''free'' THEN ''none'' ELSE ''active'' END,plan_renews_at=CASE WHEN a.message=''free'' THEN NULL ELSE now()+interval ''30 days'' END,credits=credits+a.amount,updated_at=now() WHERE id=p.id; IF a.amount>0 THEN INSERT INTO public.credit_ledger(user_id,amount,reason) VALUES(p.id,a.amount,''Telegram confirmed plan grant: ''||a.reason||'' [''||a.id::text||'']''); END IF; _result=jsonb_build_object(''plan'',a.message,''credits_added'',a.amount); ELSIF a.kind=''status'' THEN'); EXECUTE d; END; $$;
CREATE OR REPLACE FUNCTION public.telegram_queue_ticket_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.telegram_admin_config; BEGIN SELECT * INTO c FROM public.telegram_admin_config WHERE id=true; IF c.enabled THEN INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message) VALUES('ticket:'||NEW.id::text,c.admin_chat_id,'New Telegram '||NEW.kind||' ticket '||NEW.id::text||'. Review privately on https://modernnova.in/telegram. No complaint text or generated file is included.') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER telegram_ticket_notice AFTER INSERT ON public.telegram_tickets FOR EACH ROW EXECUTE FUNCTION public.telegram_queue_ticket_notice();
REVOKE ALL ON FUNCTION public.telegram_confirm_action(uuid,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_confirm_action(uuid,text,text,boolean) TO service_role;